// The parameters the owner's real sequences give the effects whose exports can only be compared statistically, as they
// stand in the sequence files, so the frame by frame comparison covers what the real show plays. Twinkle and Dissolve play on
// strips of 554 and 563 pixels at the real profile's 10 ms update interval, which the "strip" target stands in for. The values
// were read once from the show's sequence files; nothing here reads them.

namespace VixenGolden;

public static partial class Cases
{
	/// <summary>How much of a real effect plays on the long strip. Effects run longer than this on the short string.</summary>
	private const int RealStripMs = 800;

	private static void AddReal(EffectSpec s, int index, int ms, params (string, object)[] ps)
	{
		s.FrameMs = 10;
		s.Add($"real/{index}/strip", "strip", Math.Min(ms, RealStripMs), ps);
		// Several seeds, by repeating the case: its seed follows from its place in the list.
		for (var i = 0; i < 3; i++)
			s.Add($"real/{index}/string30", "string30", ms, ps);
		s.FrameMs = 50;
	}

